for i, lang in enumerate(["en", "ur", "bn", "tr"]):
    p = f"{root}/{lang}.json"
    d = json.load(open(p, encoding="utf-8"))
    for k, v in T.items():
        d.setdefault(k, v[i])
    json.dump(d, open(p, "w", encoding="utf-8"), ensure_ascii=False, separators=(",", ":"))
print("ok", len(T))
